const form = $('Recruiter Upload Form').first().json;
const pick = (o, keys) => { for (const k of keys) { if (o[k] !== undefined && o[k] !== null && String(o[k]).trim() !== '') return String(o[k]).trim(); } return ''; };
let jdText = '';
let cvText = '';
let jdError = '';
let cvError = '';
try { const j = $('Extract Job Description PDF').first().json; jdText = String(j.text || '').trim(); jdError = j.error ? String(j.error.message || j.error) : ''; } catch (e) { jdError = 'Job description PDF could not be read'; }
try { const c = $('Extract CV PDF').first().json; cvText = String(c.text || '').trim(); cvError = c.error ? String(c.error.message || c.error) : ''; } catch (e) { cvError = 'CV PDF could not be read'; }

const jobTitle = pick(form, ['job_title', 'Job Title']);
const errors = [];
if (!jobTitle) errors.push('Job title is missing');
if (jdText.length < 80) errors.push('Job description PDF has no readable text' + (jdError ? ' (' + jdError + ')' : ' - it may be a scanned image; upload a text-based PDF'));
if (cvText.length < 80) errors.push('CV PDF has no readable text' + (cvError ? ' (' + cvError + ')' : ' - it may be a scanned image; upload a text-based PDF'));

// LinkedIn URL: taken ONLY from the CV text or the recruiter's form input - never generated.
const re = /(?:https?:\/\/)?(?:[a-z]{2,3}\.)?linkedin\.com\/in\/[A-Za-z0-9_%\-]+/i;
const fromCv = (cvText.match(re) || [''])[0];
const fromForm = (pick(form, ['linkedin_url', 'Candidate LinkedIn URL (optional - used if the CV has no link)']).match(re) || [''])[0];
let linkedin = fromCv || fromForm;
if (linkedin && !linkedin.toLowerCase().startsWith('http')) linkedin = 'https://' + linkedin;

return [{ json: {
  valid: errors.length === 0,
  errors: errors,
  message: errors.length === 0 ? 'Input is valid' : 'Input validation failed: ' + errors.join('; '),
  job_title: jobTitle,
  job_description: jdText,
  candidate_resume: cvText,
  linkedin_url: linkedin,
  linkedin_source: fromCv ? 'cv' : (fromForm ? 'recruiter_input' : 'none')
} }];

