const FENCE = String.fromCharCode(96, 96, 96);
function readAi(nodeName) {
  let value;
  try {
    const out = $(nodeName).first().json.output;
    value = out && out[0] && out[0].content && out[0].content[0] ? out[0].content[0].text : undefined;
  } catch (e) {
    return null;
  }
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string' || value.trim() === '') return null;
  let s = value.trim();
  if (s.startsWith(FENCE)) {
    s = s.split(FENCE).join('');
    if (s.startsWith('json')) s = s.slice(4);
  }
  try { return JSON.parse(s.trim()); } catch (e) { return null; }
}

const checks = [
  { key: 'job', node: 'Analyze Job Description', required: ['job_title', 'mandatory_requirements', 'preferred_requirements', 'skills'] },
  { key: 'resume', node: 'Analyze Resume', required: ['name', 'skills', 'education', 'experience'] },
  { key: 'evidence', node: 'Extract Candidate Evidence', required: ['evidence'] },
  { key: 'match', node: 'Match Candidate', required: ['overall_status', 'match_score', 'strengths', 'gaps'] },
];

const result = { ai_valid: true, problems: [] };
for (const c of checks) {
  const obj = readAi(c.node);
  if (!obj) {
    result.ai_valid = false;
    result.problems.push(c.node + ': empty or invalid JSON output');
    continue;
  }
  const missing = c.required.filter((k) => !(k in obj));
  if (missing.length) {
    result.ai_valid = false;
    result.problems.push(c.node + ': missing fields ' + missing.join(', '));
  }
  result[c.key] = obj;
}
return [{ json: result }];

const url = $('Validate Input').first().json.linkedin_url || '';
const source = $('Validate Input').first().json.linkedin_source;
if (!url) {
  return [{ json: { linkedin_status: 'no_linkedin_url', linkedin_url: '', linkedin_source: 'none', profile: null, note: 'No linkedin.com/in/ URL found in the CV text or the form. Links hidden behind text in a PDF are not always extractable - add the URL in the form to check it.' } }];
}
let items = [];
try { items = $('Fetch LinkedIn Profile').all().map((i) => i.json); } catch (e) { items = []; }
const errorItem = items.find((j) => j && j.error);
const profile = items.find((j) => j && !j.error && (Array.isArray(j.experience) || Array.isArray(j.education) || j.firstName));
if (!profile) {
  return [{ json: { linkedin_status: 'fetch_failed', linkedin_url: url, linkedin_source: source, profile: null, note: errorItem ? 'LinkedIn lookup failed: ' + String(errorItem.error.message || errorItem.error).slice(0, 300) : 'LinkedIn lookup returned no profile (private, removed, or scraper unavailable).' } }];
}
const cut = (v, n) => (v === undefined || v === null ? '' : String(v).slice(0, n));
const dateText = (d) => (d && typeof d === 'object' ? (d.text || [d.month, d.year].filter(Boolean).join(' ')) : cut(d, 30));
const clean = (o) => {
  const out = {};
  for (const k of Object.keys(o || {})) {
    const v = o[k];
    if (k === 'startDate' || k === 'endDate') out[k] = dateText(v);
    else if (typeof v === 'string') out[k] = cut(v, k === 'description' ? 300 : 200);
    else if (typeof v === 'number' || typeof v === 'boolean') out[k] = v;
  }
  return out;
};
return [{ json: {
  linkedin_status: 'fetched',
  linkedin_url: url,
  linkedin_source: source,
  profile: {
    name: [profile.firstName, profile.lastName].filter(Boolean).join(' '),
    headline: cut(profile.headline, 200),
    location: profile.location && profile.location.linkedinText ? profile.location.linkedinText : '',
    experience: (profile.experience || []).slice(0, 15).map(clean),
    education: (profile.education || []).slice(0, 10).map(clean),
    certifications: (profile.certifications || []).slice(0, 10).map(clean)
  },
  note: 'Profile data retrieved live from LinkedIn via Apify scraper'
} }];

