// Deterministic checks on the CV's own work history. Never guesses missing dates.
const ai = $('Check AI Output').first().json;
const resume = ai.resume || {};
const job = ai.job || {};
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
const now = new Date();
function toIndex(v, isEnd) {
  const s = String(v || '').toLowerCase().trim();
  if (!s) return null;
  if (['present', 'current', 'now', 'till date', 'to date'].includes(s)) return now.getFullYear() * 12 + now.getMonth();
  let m = s.match(/^(\d{4})[-\/](\d{1,2})/);
  if (m) return Number(m[1]) * 12 + Number(m[2]) - 1;
  m = s.match(/^(\d{1,2})[-\/](\d{4})$/);
  if (m) return Number(m[2]) * 12 + Number(m[1]) - 1;
  m = s.match(/([a-z]{3})[a-z]*\.?\s+(\d{4})/);
  if (m && MONTHS[m[1]]) return Number(m[2]) * 12 + MONTHS[m[1]] - 1;
  m = s.match(/^(\d{4})$/);
  if (m) return Number(m[1]) * 12 + (isEnd ? 11 : 0);
  return null;
}
const issues = [];
const roles = [];
for (const r of resume.experience || []) {
  const s = toIndex(r.start_date, false);
  const e = toIndex(r.end_date, true);
  if (s === null) issues.push((r.company || 'Unknown company') + ': start date missing or unreadable');
  if (e === null) issues.push((r.company || 'Unknown company') + ': end date missing or unreadable');
  if (s !== null && e !== null) {
    if (e < s) issues.push((r.company || 'Unknown company') + ': end date is before start date');
    else roles.push({ company: r.company, s: s, e: e });
  }
}
roles.sort((a, b) => a.s - b.s);
const gaps = [];
const overlaps = [];
for (let i = 1; i < roles.length; i++) {
  const prev = roles[i - 1];
  const cur = roles[i];
  if (cur.s - prev.e > 6) gaps.push(prev.company + ' -> ' + cur.company + ': ' + (cur.s - prev.e) + ' month gap');
  if (prev.e - cur.s > 1) overlaps.push(prev.company + ' and ' + cur.company + ' overlap by ' + (prev.e - cur.s) + ' months');
}
// Total experience without double-counting overlaps
let months = 0;
let lastEnd = -1;
for (const r of roles) {
  const start = Math.max(r.s, lastEnd + 1);
  if (r.e >= start) months += r.e - start + 1;
  lastEnd = Math.max(lastEnd, r.e);
}
const years = Math.round((months / 12) * 10) / 10;
const reqs = [].concat(job.mandatory_requirements || [], job.experience_requirements || []);
const minYears = reqs.reduce((m, r) => Math.max(m, Number(r && r.minimum_years) || 0), 0);
let experience_vs_requirement = 'no_minimum_stated';
if (minYears > 0) experience_vs_requirement = roles.length === 0 ? 'cannot_calculate' : (years >= minYears ? 'meets_minimum' : 'below_minimum');
return [{ json: {
  total_experience_years: roles.length ? years : null,
  required_minimum_years: minYears || null,
  experience_vs_requirement: experience_vs_requirement,
  employment_gaps: gaps,
  overlapping_roles: overlaps,
  date_issues: issues,
  roles_with_valid_dates: roles.length,
  roles_in_cv: (resume.experience || []).length
} }];

