const FENCE = String.fromCharCode(96, 96, 96);
function parse(v) {
  if (v && typeof v === 'object') return v;
  if (typeof v !== 'string') return null;
  let s = v.trim();
  if (s.startsWith(FENCE)) { s = s.split(FENCE).join(''); if (s.startsWith('json')) s = s.slice(4); }
  try { return JSON.parse(s.trim()); } catch (e) { return null; }
}
const esc = (v) => String(v === undefined || v === null || v === '' ? '-' : v).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const ai = $('Check AI Output').first().json;
const input = $('Validate Input').first().json;
const li = $('Prepare LinkedIn Data').first().json;
const cmp = parse($('Compare CV vs LinkedIn').first().json.output[0].content[0].text) || { overall: 'not_verified', summary: 'LinkedIn comparison output could not be read', education_checks: [], experience_checks: [] };
const tl = $('Check CV Timeline').first().json;
let summary = '';
try { summary = $('Generate Recruiter Summary').first().json.output[0].content[0].text; } catch (e) { summary = ''; }
const m = ai.match || {};
const r = ai.resume || {};
const label = { strong_match: 'STRONG MATCH', possible_match: 'POSSIBLE MATCH', weak_match: 'WEAK MATCH', manual_review: 'MANUAL REVIEW' };
const list = (arr) => (arr && arr.length ? '<ul>' + arr.map((x) => '<li>' + esc(typeof x === 'object' ? JSON.stringify(x) : x) + '</li>').join('') + '</ul>' : '<p>None</p>');

let h = '';
h += '<h3>Match status: ' + esc(label[m.overall_status] || m.overall_status) + ' - ' + esc(m.match_score) + '/100</h3>';
