h += '<tr><th>Preferred requirements met</th><td>' + esc(m.preferred_requirements_met) + ' of ' + esc(m.preferred_requirements_total) + '</td></tr>';
h += '<tr><th>Experience (from CV dates)</th><td>' + esc(tl.total_experience_years) + ' years' + (tl.required_minimum_years ? ' (required: ' + esc(tl.required_minimum_years) + ', ' + esc(tl.experience_vs_requirement) + ')' : '') + '</td></tr>';
h += '<tr><th>LinkedIn check</th><td>' + esc(String(cmp.overall || 'not_verified').toUpperCase()) + ' - ' + esc(li.linkedin_status) + (li.linkedin_url ? ' (' + esc(li.linkedin_url) + ', source: ' + esc(li.linkedin_source) + ')' : '') + '</td></tr>';
h += '<tr><th>Contact (from CV only)</th><td>' + esc(r.email) + ' / ' + esc(r.phone) + '</td></tr></table>';
h += '<h3>Recruiter summary</h3><p>' + esc(summary) + '</p>';
h += '<h3>Requirement match</h3><table><tr><th>Requirement</th><th>Mandatory</th><th>Met</th><th>Explanation</th></tr>';
for (const q of m.requirement_matches || []) h += '<tr><td>' + esc(q.requirement) + '</td><td>' + (q.mandatory ? 'Yes' : 'No') + '</td><td>' + esc(q.met) + '</td><td>' + esc(q.explanation) + '</td></tr>';
h += '</table>';
h += '<h3>Strengths</h3>' + list(m.strengths);
h += '<h3>Gaps</h3>' + list(m.gaps);
h += '<h3>LinkedIn vs CV - Education</h3>';
if ((cmp.education_checks || []).length) {
  h += '<table><tr><th>CV</th><th>LinkedIn</th><th>Status</th><th>Notes</th></tr>';
  for (const c of cmp.education_checks) h += '<tr><td>' + esc(c.cv_item) + '</td><td>' + esc(c.linkedin_item) + '</td><td>' + esc(c.status) + '</td><td>' + esc(c.notes) + '</td></tr>';
  h += '</table>';
} else h += '<p>Not verified. ' + esc(li.note) + '</p>';
h += '<h3>LinkedIn vs CV - Experience</h3>';
if ((cmp.experience_checks || []).length) {
  h += '<table><tr><th>CV</th><th>LinkedIn</th><th>Title</th><th>Dates</th><th>Notes</th></tr>';
  for (const c of cmp.experience_checks) h += '<tr><td>' + esc(c.cv_item) + '</td><td>' + esc(c.linkedin_item) + '</td><td>' + esc(c.title_status) + '</td><td>' + esc(c.dates_status) + '</td><td>' + esc(c.notes) + '</td></tr>';
  h += '</table>';
} else h += '<p>Not verified. ' + esc(li.note) + '</p>';
h += '<p><b>LinkedIn summary:</b> ' + esc(cmp.summary) + '</p>';
h += '<h3>CV timeline checks</h3>' + list([].concat(tl.employment_gaps || [], tl.overlapping_roles || [], tl.date_issues || []));
h += '<h3>Manual review items</h3>' + list(m.manual_review_items);
h += '<p><i>The AI does not make hiring decisions. Verify key facts before submitting the candidate.</i></p>';

return [{ json: { dashboard_html: h, match_status: m.overall_status, match_score: m.match_score, linkedin_overall: cmp.overall, linkedin_comparison: cmp, timeline: tl, summary: summary } }];

