const ai = $('Check AI Output').first().json;
const dash = $('Build Dashboard').first().json;
const review = $('Recruiter Review Dashboard').first().json;
const decision = String(review.recruiter_decision || review['Recruiter Decision'] || '').toUpperCase();
let status;
let submission = '';
if (decision === 'APPROVE') {
  status = 'approved_for_submission';
  submission = $json.output && $json.output[0] ? $json.output[0].content[0].text : '';
} else {
  status = $json.status;
  submission = $json.message;
}
const esc = (v) => String(v || '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const html = '<h2>Decision recorded: ' + esc(decision) + '</h2>' +
  '<p>Match status: <b>' + esc(dash.match_status) + '</b> (' + esc(dash.match_score) + '/100) - LinkedIn check: <b>' + esc(dash.linkedin_overall) + '</b></p>' +
  '<pre style="white-space:pre-wrap;text-align:left">' + esc(submission) + '</pre>';
return [{ json: {
  status: status,
  recruiter_decision: decision,
  recruiter_notes: review.recruiter_notes || '',
  candidate: ai.resume,
  job: ai.job,
  match: ai.match,
  linkedin_comparison: dash.linkedin_comparison,
  timeline: dash.timeline,
  summary: dash.summary,
  submission: submission,
  result_html: html
} }];
